namespace RonSijm.FluidHumidifier.Factories.SageMaker;

public class TransformJobFactory(string resourceName = null, Action<Humidifier.SageMaker.TransformJob> factoryAction = null) : ResourceFactory<Humidifier.SageMaker.TransformJob>(resourceName)
{

    internal List<InnerTransformJobTagsItemsFactory> TagsFactories { get; set; } = [];

    internal InnerTransformJobTransformOutputFactory TransformOutputFactory { get; set; }

    internal InnerTransformJobTransformInputFactory TransformInputFactory { get; set; }

    internal InnerTransformJobDataProcessingFactory DataProcessingFactory { get; set; }

    internal InnerTransformJobDataCaptureConfigFactory DataCaptureConfigFactory { get; set; }

    internal InnerTransformJobTransformResourcesFactory TransformResourcesFactory { get; set; }

    internal InnerTransformJobModelClientConfigFactory ModelClientConfigFactory { get; set; }

    internal InnerTransformJobExperimentConfigFactory ExperimentConfigFactory { get; set; }

    protected override Humidifier.SageMaker.TransformJob Create()
    {
        var transformJobResult = CreateTransformJob();
        factoryAction?.Invoke(transformJobResult);

        return transformJobResult;
    }

    private Humidifier.SageMaker.TransformJob CreateTransformJob()
    {
        var transformJobResult = new Humidifier.SageMaker.TransformJob
        {
            GivenName = InputResourceName,
        };

        return transformJobResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.TransformJob result)
    {
        base.CreateChildren(result);

        result.Tags = TagsFactories.Any() ? TagsFactories.Select(x => x.Build()).ToList() : null;
        result.TransformOutput ??= TransformOutputFactory?.Build();
        result.TransformInput ??= TransformInputFactory?.Build();
        result.DataProcessing ??= DataProcessingFactory?.Build();
        result.DataCaptureConfig ??= DataCaptureConfigFactory?.Build();
        result.TransformResources ??= TransformResourcesFactory?.Build();
        result.ModelClientConfig ??= ModelClientConfigFactory?.Build();
        result.ExperimentConfig ??= ExperimentConfigFactory?.Build();
    }

} // End Of Class

